  computed: {
    advertId() {
      return this.queries?.id || this.queries?.advert;
    },

    hiringClosed() {
      return this.advert.hiringStatus?.code === "closed";
    },

    // Distinct from the application open/closed status above — an advert
    // can stop accepting applications while hiring is still ongoing, or
    // hiring can be explicitly closed (see close-hiring) independently of
    // the advert's own dates.
    hiringStatusCode() {
      return this.advert.hiringStatus?.code || "ongoing";
    },
    hiringStatusLabel() {
      return (
        this.advert.hiringStatus?.display ||
        { ongoing: "Hiring Ongoing", pending: "Hiring Pending", closed: "Hiring Closed" }[
          this.hiringStatusCode
        ] ||
        "Hiring Ongoing"
      );
    },

    today() {
      return new Date().toISOString().split("T")[0];
    },

    isOpen() {
      if (this.hiringClosed) return false;
      if (!this.advert.openDate || !this.advert.closingDate) return false;
      return (
        this.advert.openDate <= this.today &&
        this.advert.closingDate >= this.today
      );
    },

    isClosingSoon() {
      if (this.hiringClosed) return false;
      if (!this.advert.closingDate) return false;
      const diff = new Date(this.advert.closingDate) - new Date();
      return diff > 0 && diff < 7 * 86400000;
    },

    daysRemaining() {
      if (!this.advert.closingDate) return 0;
      return Math.ceil(
        (new Date(this.advert.closingDate) - new Date()) / 86400000,
      );
    },

    advertisementDays() {
      if (!this.advert.openDate || !this.advert.closingDate) return 0;
      return Math.floor(
        (new Date(this.advert.closingDate) - new Date(this.advert.openDate)) /
          86400000,
      );
    },

    closingProgress() {
      if (!this.advert.openDate || !this.advert.closingDate) return 0;
      const total =
        new Date(this.advert.closingDate) - new Date(this.advert.openDate);
      const elapsed = new Date() - new Date(this.advert.openDate);
      return Math.min(Math.max((elapsed / total) * 100, 0), 100);
    },

    countdownClass() {
      if (this.daysRemaining < 0) return "vd-countdown--expired";
      if (this.isClosingSoon) return "vd-countdown--urgent";
      if (this.isOpen) return "vd-countdown--open";
      return "vd-countdown--pending";
    },

    isExpired() {
      return !!this.advert.closingDate && this.daysRemaining < 0;
    },

    daysLabel() {
      if (this.daysRemaining === 0) return "closing today";
      return this.daysRemaining < 0 ? "days ago" : "days remaining";
    },

    // When the closing date has passed but the stored stage is still
    // "advertised", treat it as "applications_closed" for display purposes.
    effectiveStage() {
      if (this.isExpired && this.advert.stage === "advertised") {
        return "applications_closed";
      }
      return this.advert.stage;
    },

    countdownBarColor() {
      if (this.daysRemaining < 0) return "#6b7280";
      if (this.isClosingSoon) return "#ef4444";
      if (this.closingProgress > 70) return "#f97316";
      return "#0d9488";
    },

    pipeline() {
      return [
        {
          code: "advertised",
          name: "Advertised",
          icon: "mdi-bullhorn-outline",
        },
        {
          code: "applications_closed",
          name: "Apps Closed",
          icon: "mdi-lock-outline",
        },
        {
          code: "shortlisting",
          name: "Shortlisting",
          icon: "mdi-format-list-checks",
        },
        {
          code: "psc_submitted",
          name: "PSC Submitted",
          icon: "mdi-send-outline",
        },
        {
          code: "psc_endorsed",
          name: "PSC Endorsed",
          icon: "mdi-shield-check-outline",
        },
        {
          code: "appointment_pending",
          name: "Appt. Ready",
          icon: "mdi-file-sign",
        },
        {
          code: "onboarding",
          name: "Onboarding",
          icon: "mdi-account-check-outline",
        },
      ];
    },
  },

  async mounted() {
    if (!this.advertId) {
      this.notFound = true;
      this.loading = false;
      return;
    }
    await this.loadAdvert();
  },

  methods: {
    // ── Load advertisement FHIR resource ──────────────────────────────
    async loadAdvert() {
      this.loading = true;
      try {
        const res = await fetch(`/fhir/Basic/${this.advertId}`);
        if (!res.ok) {
          this.notFound = true;
          return;
        }
        const data = await res.json();

        this.advert = {
          id: data.id,
          name: this.getExt(data, EXT.ADV_NAME, "valueString") || "",
          description:
            this.getExt(data, EXT.ADV_DESCRIPTION, "valueString") || "",
          designation: this.getExt(data, EXT.ADV_NAME, "valueString") || "",
          advertisedDate:
            this.getExt(data, EXT.EVENT_DATE, "valueDate") || null,
          openDate: this.getExt(data, EXT.ADV_START, "valueDate") || null,
          closingDate: this.getExt(data, EXT.ADV_END, "valueDate") || null,
          advertisedVacancies:
            this.getExt(data, EXT.ADV_MAX, "valueInteger") || 0,
          employmentCategory:
            this.getExt(data, EXT.EMP_CAT, "valueCoding") || null,
          employmentEnd: this.getExt(data, EXT.EMP_END, "valueDate") || null,
          hiringStatus:
            this.getExt(data, EXT.HIRING_STATUS, "valueCoding") || null,
          applicationsCount: 0,
          stage: "advertised",
          positionRef: null,
        };

        const posRef = this.getExt(data, EXT.ADV_POSITION, "valueReference");
        if (posRef && posRef.reference) {
          this.advert.positionRef = posRef.reference;
          this.loadingPosition = true;
          await this.resolvePosition(posRef.reference);
          this.loadingPosition = false;
        }

        // Fetch application count in background (non-blocking)
        this.loadApplicationsCount();
      } catch (err) {
        console.error("loadAdvert error", err);
        this.notFound = true;
      } finally {
        this.loading = false;
      }
    },

    // ── Fetch application count for this advert ───────────────────────
    async loadApplicationsCount() {
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/application-profile",
          advertisedvacancy: "Basic/" + this.advert.id,
          _count: "0",
          _total: "accurate",
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) return;
        const bundle = await res.json();
        this.$set(this.advert, "applicationsCount", bundle.total || 0);
      } catch (err) {
        // Non-fatal — count stays 0
      }
    },

    // ── Resolve linked position resource ──────────────────────────────
    async resolvePosition(positionReference) {
      try {
        const posId = positionReference.split("/")[1];
        const posRes = await fetch(`/fhir/Basic/${posId}`);
        if (!posRes.ok) return;
        const pos = await posRes.json();

        const details = {
          designation: "",
          grade: "",
          department: "",
          facility: "",
          district: "",
          maxPosts:
            this.getExt(pos, EXT.MAX_PRACTITIONERS, "valueInteger") || 0,
          filled: 0,
          vacantPosts: 0,
          posDescription:
            this.getExt(pos, EXT.ADV_DESCRIPTION, "valueString") || "",
          minimumRequirements:
            this.getExt(pos, EXT.MINIMUM_REQUIREMENTS, "valueString") || "",
          additionalRequirements:
            this.getExt(pos, EXT.ADDITIONAL_REQUIREMENTS, "valueString") || "",
        };

        // ── Designation name ──────────────────────────────────────────
        const desigRef = this.getExt(pos, EXT.DESIGNATION, "valueReference");
        if (desigRef?.reference) {
          try {
            const dId = desigRef.reference.split("/")[1];
            const dRes = await fetch(`/fhir/Basic/${dId}`);
            const d = await dRes.json();
            details.designation =
              this.getExt(d, EXT.POS_NAME, "valueString") || "";
          } catch (err) {
            // ignore
          }
        }

        // ── Salary grade ──────────────────────────────────────────────
        const gradeRef = this.getExt(pos, EXT.GRADE, "valueReference");
        if (gradeRef?.reference) {
          try {
            const gId = gradeRef.reference.split("/")[1];
            const gRes = await fetch(`/fhir/Basic/${gId}`);
            const g = await gRes.json();
            details.grade = this.getExt(g, EXT.POS_NAME, "valueString") || "";
          } catch (err) {
            // ignore
          }
        }

        // ── Department ────────────────────────────────────────────────
        const deptCoding = this.getExt(pos, EXT.DEPARTMENT, "valueCoding");
        if (deptCoding) {
          details.department = deptCoding.display || deptCoding.code || "";
        }

        // ── Facility + district chain via Location hierarchy ──────────
        const facRef = this.getExt(pos, EXT.FACILITY, "valueReference");
        if (facRef?.reference) {
          try {
            const fRes = await fetch(`/fhir/${facRef.reference}`);
            const fData = await fRes.json();
            details.facility = fData.name || "";

            if (fData.partOf?.reference) {
              const cRes = await fetch(`/fhir/${fData.partOf.reference}`);
              const cData = await cRes.json();
              if (cData.partOf?.reference) {
                const distRes = await fetch(`/fhir/${cData.partOf.reference}`);
                const distData = await distRes.json();
                details.district = distData.name || "";
              }
            }
          } catch (err) {
            // ignore
          }
        }

        // ── Filled / vacant count (mirror of position report logic) ──
        try {
          const roleRes = await fetch(
            `/fhir/PractitionerRole?roleposition=Basic/${posId}&active=true&_summary=count`,
          );
          const roleData = await roleRes.json();
          details.filled = roleData.total || 0;
          details.vacantPosts = Math.max(0, details.maxPosts - details.filled);
        } catch (err) {
          details.filled = 0;
          details.vacantPosts = details.maxPosts;
        }

        this.position = details;
        this.positionResource = pos;

        // Keep advert designation in sync if designation resolved
        if (details.designation && !this.advert.designation) {
          this.advert.designation = details.designation;
        }
      } catch (err) {
        console.error("resolvePosition error", err);
      }
    },

    // ── Navigation ────────────────────────────────────────────────────
    goBack() {
      this.$router.push({
        path: "/custom/index",
        query: { path: "/lesotho/components/recruitment" },
      });
    },

    editAdvert() {
      if (this.hiringClosed) return;
      this.$router.push({
        path: "/custom/advertise-position",
        query: {
          path: "/lesotho/components/recruitment",
          advert: this.advert.id,
        },
      });
    },

    viewApplications() {
      this.$router.push({
        path: "/custom/applicant-list",
        query: {
          path: "/lesotho/components/recruitment",
          advertId: this.advert.id,
          from: "vacancy-detail",
        },
      });
    },

    // ── Pipeline helpers ──────────────────────────────────────────────
    advertFields() {
      const f = this.advert;
      const rows = [
        {
          label: "Advertised Date",
          value: this.formatDate(f.advertisedDate),
          mono: true,
          hint: "Date advert was published",
        },
        {
          label: "Open Date",
          value: this.formatDate(f.openDate),
          mono: true,
          hint: "Position acceptance start date",
        },
        {
          label: "Closing Date",
          value: this.formatDate(f.closingDate),
          mono: true,
          hint: "Final date for applications",
          red: this.isClosingSoon,
        },
        {
          label: "Duration",
          value: this.advertisementDays + " days",
          chip: true,
          hint: "Total advertisement period",
        },
        {
          label: "Advertised Vacancies",
          value: f.advertisedVacancies,
          big: true,
          hint: "Posts advertised in this notice",
        },
        {
          label: "Applications Received",
          value: f.applicationsCount,
          big: true,
          hint: "Total applications to date",
        },
        {
          label: "Employment Category",
          value: (f.employmentCategory && f.employmentCategory.display) || "—",
          hint: "Type of employment offered",
        },
      ];
      if (f.employmentEnd)
        rows.push({
          label: "Employment End Date",
          value: this.formatDate(f.employmentEnd),
          mono: true,
          hint: "Contract / engagement end date",
        });
      return rows;
    },

    summaryItems() {
      return [
        {
          icon: "mdi-calendar-check",
          label: "Advertised On",
          value: this.formatDate(this.advert.advertisedDate),
        },
        {
          icon: "mdi-calendar-start",
          label: "Opens",
          value: this.formatDate(this.advert.openDate),
        },
        {
          icon: "mdi-calendar-end",
          label: "Closes",
          value: this.formatDate(this.advert.closingDate),
          red: this.isClosingSoon,
        },
      ];
    },

    isPastStage(code) {
      const currentIdx = STAGE_ORDER.indexOf(this.effectiveStage);
      const codeIdx = STAGE_ORDER.indexOf(code);
      return codeIdx < currentIdx;
    },

    pipelineIconColor(code) {
      if (this.effectiveStage === code) return "#ffffff";
      if (this.isPastStage(code)) return "#0d9488";
      return "#9ca3af";
    },

    // ── Display helpers ───────────────────────────────────────────────
    stageColor(stage) {
      const m = {
        advertised: "#0d9488",
        applications_closed: "#f97316",
        shortlisting: "#6366f1",
        psc_submitted: "#7c3aed",
        psc_endorsed: "#0d9488",
        appointment_pending: "#f97316",
        onboarding: "#0d9488",
      };
      return m[stage] || "#a8a29e";
    },

    stageName(stage) {
      const m = {
        advertised: "Advertised",
        applications_closed: "Apps Closed",
        shortlisting: "Shortlisting",
        psc_submitted: "PSC Submitted",
        psc_endorsed: "PSC Endorsed",
        appointment_pending: "Appt. Ready",
        onboarding: "Onboarding",
      };
      return m[stage] || stage;
    },

    formatDate(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    getExt(resource, url, type) {
      const ext =
        resource &&
        resource.extension &&
        resource.extension.find((e) => e.url === url);
      return ext ? ext[type] : null;
    },
  },
};
</script>

